def prepare_decode(self, seqs: list[Sequence]): input_ids = [] # (1) 每个 seq 的最后一个 token positions = [] # (2) 最后一个 token 的位置 slot_mapping = [] # (3) 写入 KV cache 的槽位（每个 seq 1 个 slot） context_lens = [] # (4) 每个 seq 当前的总上下文长度
for seq in seqs: input_ids.append(seq.last_token) # (5a) 只传最后 1 token positions.append(len(seq) - 1) # (5b) 位置 = 总 token 数 - 1 context_lens.append(len(seq)) # (5c) 上下文长度 # (5d) 槽位 = 最后块的起始slot + 块内偏移 - 1 slot_mapping.append(seq.block_table[-1] * self.block_size + seq.last_block_num_tokens - 1)
input_ids = torch.tensor(input_ids, dtype=torch.int64, pin_memory=True).cuda(non_blocking=True) positions = torch.tensor(positions, dtype=torch.int64, pin_memory=True).cuda(non_blocking=True) slot_mapping = torch.tensor(slot_mapping, dtype=torch.int32, pin_memory=True).cuda(non_blocking=True) context_lens = torch.tensor(context_lens, dtype=torch.int32, pin_memory=True).cuda(non_blocking=True) block_tables = self.prepare_block_tables(seqs) # (6) 始终需要 block_tables set_context(False, slot_mapping=slot_mapping, context_lens=context_lens, block_tables=block_tables) return input_ids, positions

