def loop(self):
    while True:
        method_name, args = self.read_shm()                # (1) 阻塞等待主进程发指令
        self.call(method_name, *args)                      # (2) 执行方法
        if method_name == "exit":                          # (3) 收到 exit 指令则退出循环
            break

def exit(self):
    if self.world_size > 1:
        self.shm.close()                             # (1) 关闭 SharedMemory 映射
        dist.barrier()                               # (2) 同步所有 rank
        if self.rank == 0:
            self.shm.unlink()                        # (3) 主进程删除共享内存文件
    if not self.enforce_eager:
        del self.graphs, self.graph_pool             # (4) 释放 CUDA Graph 资源
    torch.cuda.synchronize()                         # (5) 等待所有 GPU 操作完成
    dist.destroy_process_group()                     # (6) 销毁 NCCL 进程组

@dataclass(slots=True) class Context: is_prefill: bool = False # Prefill 或 Decode cu_seqlens_q: torch.Tensor | None = None # Q 累积长度（varlen attention 用） cu_seqlens_k: torch.Tensor | None = None # K 累积长度（不含前缀缓存的 Q 长度） max_seqlen_q: int = 0 max_seqlen_k: int = 0 slot_mapping: torch.Tensor | None = None # token → KV cache 槽位映射 context_lens: torch.Tensor | None = None # 每个 seq 的上下文长度（decode 用） block_tables: torch.Tensor | None = None # block table（含 padding -1）
# ==== 模块级全局变量 ==== _CONTEXT = Context() # (1) 初始化为空 Context
def get_context(): # (2) 只读访问 return _CONTEXT
def set_context(is_prefill, ...): # (3) 写入新 Context（替换而非修改） global _CONTEXT _CONTEXT = Context(is_prefill, ...)
def reset_context(): # (4) 重置为空 Context global _CONTEXT _CONTEXT = Context()
